import { query, pool } from '../src/config/database';
import { adminQuery, closeAdminPool } from '../src/tests/test-admin';

/**
 * Script: cleanup-synthetic-data.ts
 * Purpose: Identify and remove confirmed disposable synthetic/demo records
 *          generated by earlier analytics seed runs.
 *
 * Usage:
 *   bun run scripts/cleanup-synthetic-data.ts           # Dry-run inspection
 *   bun run scripts/cleanup-synthetic-data.ts --confirm # Execute deletion transaction
 */

async function main() {
  const isConfirm = process.argv.includes('--confirm');

  console.log(`[cleanup] Mode: ${isConfirm ? 'EXECUTE (DESTRUCTIVE)' : 'DRY-RUN (INSPECTION ONLY)'}`);

  // 1. Audit matching synthetic rows
  const runsCount = await adminQuery<{ count: string }>(`
    SELECT COUNT(*) as count FROM public.workflow_runs
    WHERE name LIKE 'Patient Call #%';
  `);

  const apptsCount = await query<{ count: string }>(`
    SELECT COUNT(*) as count FROM business_ext.appointments
    WHERE notes = 'Scheduled via AI voice intake';
  `);

  const interactionsCount = await query<{ count: string }>(`
    SELECT COUNT(*) as count FROM business_ext.interactions
    WHERE summary = 'Autonomous call successfully resolved';
  `);

  const dummyEmails = [
    'sarah.c@example.com',
    'm.scott@dunder.com',
    'elena.r@example.org',
    'dmiller@company.io',
    'amanda.b@example.net',
    'j.holden@roci.org',
    'naomi.n@belt.com',
    'alex.k@mars.gov',
  ];

  const contactsCount = await query<{ count: string }>(`
    SELECT COUNT(*) as count FROM business_ext.contacts
    WHERE email = ANY($1::text[]);
  `, [dummyEmails]);

  console.log('[cleanup] Identified synthetic records:');
  console.log(`  - workflow_runs ("Patient Call #%"): ${runsCount.rows[0]?.count || 0}`);
  console.log(`  - business_ext.appointments ("Scheduled via AI voice intake"): ${apptsCount.rows[0]?.count || 0}`);
  console.log(`  - business_ext.interactions ("Autonomous call successfully resolved"): ${interactionsCount.rows[0]?.count || 0}`);
  console.log(`  - business_ext.contacts (known demo emails): ${contactsCount.rows[0]?.count || 0}`);

  if (!isConfirm) {
    console.log('\n[cleanup] Dry run complete. No records modified.');
    console.log('[cleanup] Pass --confirm to execute deletion in a single database transaction.');
    await pool.end();
    await closeAdminPool();
    process.exit(0);
  }

  // Execute within transaction
  console.log('\n[cleanup] Beginning transactional purge of synthetic data...');
  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    const delAppts = await client.query(`
      DELETE FROM business_ext.appointments
      WHERE notes = 'Scheduled via AI voice intake';
    `);
    console.log(`  [✓] Deleted ${delAppts.rowCount} appointments`);

    const delInteractions = await client.query(`
      DELETE FROM business_ext.interactions
      WHERE summary = 'Autonomous call successfully resolved';
    `);
    console.log(`  [✓] Deleted ${delInteractions.rowCount} interactions`);

    const delContacts = await client.query(`
      DELETE FROM business_ext.contacts
      WHERE email = ANY($1::text[]);
    `, [dummyEmails]);
    console.log(`  [✓] Deleted ${delContacts.rowCount} contacts`);

    // Purge public.workflow_runs using adminQuery (requires higher privilege)
    const delRuns = await adminQuery(`
      DELETE FROM public.workflow_runs
      WHERE name LIKE 'Patient Call #%';
    `);
    console.log(`  [✓] Deleted synthetic workflow_runs`);

    await client.query('COMMIT');
    console.log('[cleanup] All disposable synthetic records purged successfully.');
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('[cleanup] Transaction rolled back due to error:', error);
    process.exit(1);
  } finally {
    client.release();
    await pool.end();
    await closeAdminPool();
  }
}

main().catch((err) => {
  console.error('[cleanup] Fatal error:', err);
  process.exit(1);
});
